(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10+Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10+Math.cos((x-y)*0.012-t*0.4)*8;
  const sx = x+wx, sy = y+wy;
  const wx2 = Math.sin(sx*0.03+t*0.7)*6+Math.cos(sy*0.025-t*0.6)*5;
  const wy2 = Math.cos(sy*0.03-t*0.65)*6+Math.sin(sx*0.028+t*0.55)*5;
  const dx = sx+wx2, dy = sy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+2)*65, 0.11, 2.1, 1.05],
    [400+Math.cos(t*0.55+1)*95, 200+Math.sin(t*0.75+4)*75, 0.065, 2.4, 0.85],
    [200+Math.sin(t*0.38+6)*130, 220+Math.cos(t*0.48+3)*85, 0.085, 1.8, 1.15]
  ];
  let aS=0, iS=0, cS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((dx-sX)**2+(dy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    aS+=wave*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS+=Math.sin(d*f*1.3-t*sp*0.4+Math.sin(t*0.3)*0.5)*w*0.5;
  }
  const n=9, act=aS/n, inh=iS/n, cross=cS/n;
  const bg=(Math.sin(dx*0.04+dy*0.025+t*0.8)+Math.sin(dx*0.03-dy*0.04+t*1.1))/2+Math.sin((dx+dy)*0.12+t*2.5)*0.2+Math.sin((dx-dy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((dx-cx)**2+(dy-cy)**2), ang=Math.atan2(dy-cy,dx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.03-ang*5+t*0.9))*0.27;
  const turb=Math.sin(dx*0.08+Math.sin(dy*0.06+t)*2+t*1.3)*0.3+Math.cos(dy*0.07+Math.cos(dx*0.05-t)*2-t*1.1)*0.3;
  const feed=act-inh*0.7+bg*0.3+spiral+turb*0.4;
  const laplacian=Math.tanh(cross*1.5+Math.sin(act*inh)*0.8)*0.3;
  const reaction=Math.tanh((feed+laplacian)*2.2);
  const cell=Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15)+Math.sin((dx+dy)*0.1+t)*0.5+Math.sin(dx*0.2-dy*0.18+t*0.7)*0.3)*1.5)*0.3;
  const fiber=Math.tanh(Math.sin(ang*6+dist*0.03+t*0.8)*Math.cos(ang*4-dist*0.04+t*0.6))*0.15;
  const blend=reaction*0.6+cell*0.25+fiber*0.15, v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,45,85],[15,95,115],[25,155,145],[180,190,60],[220,140,55],[195,75,65],[120,30,55],[45,12,42],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.7?1.2:Math.abs(reaction)>0.4?1.08:1.0;
  const shimmer=0.95+Math.sin(t*3+dist*0.1)*0.05*Math.abs(reaction);
  const m=lum*edge*shimmer;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
